<?php
$pdo=db();$manage=in_array($user['role'],['Administrator','Head','Clerk'],true);$rooms=[];$allocations=[];$students=[];$parents=[];$guardianChildren=[];$currentAllocationCount=0;
if($manage){$rooms=$pdo->query("SELECT r.*,u.full_name AS house_parent,COUNT(a.id) AS occupied FROM boarding_rooms r LEFT JOIN users u ON u.id=r.house_parent_id LEFT JOIN boarding_allocations a ON a.room_id=r.id AND a.status='Active' AND a.start_on<=CURDATE() AND (a.end_on IS NULL OR a.end_on>=CURDATE()) GROUP BY r.id ORDER BY r.active DESC,r.boarding_house,r.room_name")->fetchAll();$currentAllocationCount=(int)$pdo->query("SELECT COUNT(*) FROM boarding_allocations WHERE status='Active' AND start_on<=CURDATE() AND (end_on IS NULL OR end_on>=CURDATE())")->fetchColumn();$allocations=$pdo->query("SELECT a.*,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream,s.sex,r.room_name,r.boarding_house,u.full_name AS house_parent FROM boarding_allocations a JOIN students s ON s.id=a.student_id JOIN boarding_rooms r ON r.id=a.room_id LEFT JOIN users u ON u.id=r.house_parent_id ORDER BY (a.status='Active') DESC,a.start_on DESC,a.id DESC LIMIT 300")->fetchAll();$students=$pdo->query("SELECT id,admission_no,first_name,last_name,form_level,stream,sex FROM students WHERE status='Active' ORDER BY last_name,first_name LIMIT 1500")->fetchAll();$parents=$pdo->query("SELECT id,full_name,role FROM users WHERE active=1 AND role IN ('Administrator','Head','Teacher','Clerk') ORDER BY full_name")->fetchAll();}
else{$q=$pdo->prepare("SELECT DISTINCT s.id,s.admission_no,s.first_name,s.last_name,s.form_level,s.stream FROM guardian_user_links l JOIN student_guardians g ON g.id=l.guardian_id AND g.consent_status='Granted' JOIN students s ON s.id=g.student_id WHERE l.user_id=:user ORDER BY s.last_name,s.first_name");$q->execute(['user'=>$user['id']]);$guardianChildren=$q->fetchAll();$q=$pdo->prepare("SELECT DISTINCT a.id,a.student_id,a.start_on,a.end_on,a.status,r.room_name,r.boarding_house,r.gender,u.full_name AS house_parent FROM guardian_user_links l JOIN student_guardians g ON g.id=l.guardian_id AND g.consent_status='Granted' JOIN boarding_allocations a ON a.student_id=g.student_id JOIN boarding_rooms r ON r.id=a.room_id LEFT JOIN users u ON u.id=r.house_parent_id WHERE l.user_id=:user ORDER BY a.start_on DESC,a.id DESC");$q->execute(['user'=>$user['id']]);$allocations=$q->fetchAll();}
?>
<div class="page-heading"><div><div class="eyebrow"><?= $manage?'STUDENT SERVICES · BOARDING':'FAMILY PORTAL' ?></div><h1>Boarding</h1><p class="subheading"><?= $manage?'Manage dormitory capacity and learner room assignments.':'View boarding information for your linked learners.' ?></p></div></div>
<?php if($manage): ?>
<section class="stat-strip"><div><span>Rooms / dormitories</span><b><?= count($rooms) ?></b></div><div><span>Active allocations today</span><b><?= number_format($currentAllocationCount) ?></b></div><div><span>Active rooms</span><b><?= count(array_filter($rooms,static fn($r)=>(int)$r['active']===1)) ?></b></div><div><span>Learner population</span><b><?= count($students) ?></b></div></section>
<div class="academic-two-col"><section class="panel settings-panel"><h2>Add a dormitory / room</h2><p>Room capacity counts learners with overlapping active allocations.</p><form method="post" action="actions/boarding_room_save.php" class="compact-form"><?= csrf_field() ?><label>Room name<input name="room_name" required maxlength="120" placeholder="e.g. Nyika House · Room 2"></label><label>Boarding house<input name="boarding_house" maxlength="100" placeholder="Nyika House"></label><label>Room type<select name="gender"><option>Girls</option><option>Boys</option><option>Mixed</option></select></label><label>Bed capacity<input type="number" name="capacity" min="1" max="2000" required></label><label>House parent<select name="house_parent_id"><option value="">Unassigned</option><?php foreach($parents as $parent): ?><option value="<?= (int)$parent['id'] ?>"><?= h($parent['full_name']) ?> · <?= h($parent['role']) ?></option><?php endforeach; ?></select></label><button class="primary-button">Create room</button></form></section>
<section class="panel settings-panel"><h2>Allocate a learner</h2><p>Moves close the prior allocation the day before the new room starts.</p><form method="post" action="actions/boarding_allocation_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="operation" value="assign"><label>Active learner<select name="student_id" required><option value="">Select learner</option><?php foreach($students as $student): ?><option value="<?= (int)$student['id'] ?>"><?= h($student['last_name'].', '.$student['first_name'].' · '.$student['admission_no'].' · Form '.$student['form_level'].($student['stream']?' '.$student['stream']:'')) ?></option><?php endforeach; ?></select></label><label>Active room<select name="room_id" required><option value="">Select room</option><?php foreach($rooms as $room): if($room['active']): ?><option value="<?= (int)$room['id'] ?>"><?= h($room['room_name'].' · '.$room['gender'].' · '.$room['occupied'].'/'.$room['capacity']) ?></option><?php endif; endforeach; ?></select></label><label>Start date<input type="date" name="start_on" value="<?= h(date('Y-m-d')) ?>" min="<?= h(date('Y-m-d')) ?>" required></label><label>Note <span class="optional">Optional; avoid medical details</span><input name="notes" maxlength="255"></label><button class="primary-button">Allocate room</button></form></section></div>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Dormitory rooms</h2><p>Capacity and current occupancy</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Room</th><th>House</th><th>Room type</th><th>Occupancy</th><th>House parent</th><th>Status / edit</th></tr></thead><tbody><?php foreach($rooms as $room): ?><tr><td><b><?= h($room['room_name']) ?></b></td><td><?= h($room['boarding_house']?:'—') ?></td><td><?= h($room['gender']) ?></td><td><?= (int)$room['occupied'] ?> / <?= (int)$room['capacity'] ?></td><td><?= h($room['house_parent']?:'Unassigned') ?></td><td><span class="status-pill <?= $room['active']?'':'inactive' ?>"><?= $room['active']?'Active':'Inactive' ?></span><details><summary>Edit room</summary><form method="post" action="actions/boarding_room_save.php" class="compact-form"><?= csrf_field() ?><input type="hidden" name="room_id" value="<?= (int)$room['id'] ?>"><label>Room name<input name="room_name" value="<?= h($room['room_name']) ?>" required maxlength="120"></label><label>Boarding house<input name="boarding_house" value="<?= h($room['boarding_house']??'') ?>" maxlength="100"></label><label>Room type<select name="gender"><?php foreach(['Boys','Girls','Mixed'] as $kind): ?><option <?= $room['gender']===$kind?'selected':'' ?>><?= h($kind) ?></option><?php endforeach; ?></select></label><label>Bed capacity<input type="number" name="capacity" value="<?= (int)$room['capacity'] ?>" min="1" max="2000" required></label><label>House parent<select name="house_parent_id"><option value="">Unassigned</option><?php foreach($parents as $parent): ?><option value="<?= (int)$parent['id'] ?>" <?= (int)$room['house_parent_id']===(int)$parent['id']?'selected':'' ?>><?= h($parent['full_name']) ?> · <?= h($parent['role']) ?></option><?php endforeach; ?></select></label><label><input type="checkbox" name="active" value="1" <?= $room['active']?'checked':'' ?>> Active for new allocations</label><button class="outline-button">Save room</button></form></details></td></tr><?php endforeach; if(!$rooms): ?><tr><td colspan="6" class="empty-cell">Create the school’s boarding houses and rooms to begin.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel learners-panel"><div class="panel-heading"><div><h2>Allocation history</h2><p>Latest 300 assignments and move-outs</p></div></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Room</th><th>House parent</th><th>Dates</th><th>Status / note</th><th></th></tr></thead><tbody><?php foreach($allocations as $allocation): $current=$allocation['status']==='Active'&&$allocation['start_on']<=date('Y-m-d')&&(!$allocation['end_on']||$allocation['end_on']>=date('Y-m-d')); ?><tr><td><?= h($allocation['first_name'].' '.$allocation['last_name']) ?><small class="muted-cell"><?= h($allocation['admission_no']) ?> · Form <?= (int)$allocation['form_level'] ?><?= $allocation['stream']?' '.h($allocation['stream']):'' ?></small></td><td><?= h($allocation['room_name']) ?><?= $allocation['boarding_house']?'<small class="muted-cell">'.h($allocation['boarding_house']).'</small>':'' ?></td><td><?= h($allocation['house_parent']?:'Unassigned') ?></td><td><?= h(date('d M Y',strtotime($allocation['start_on']))) ?> – <?= $allocation['end_on']?h(date('d M Y',strtotime($allocation['end_on']))):'Current' ?></td><td><span class="status-pill"><?= $current?'Current':($allocation['status']==='Active'?'Scheduled':h($allocation['status'])) ?></span><?= $allocation['notes']?'<small class="muted-cell">'.h($allocation['notes']).'</small>':'' ?></td><td><?php if($current): ?><form method="post" action="actions/boarding_allocation_save.php" class="compact-form" onsubmit="return confirm('Record this learner’s move-out?')"><?= csrf_field() ?><input type="hidden" name="operation" value="release"><input type="hidden" name="allocation_id" value="<?= (int)$allocation['id'] ?>"><label>Move-out date<input type="date" name="end_on" min="<?= h(date('Y-m-d')) ?>" value="<?= h(date('Y-m-d')) ?>" required></label><button class="outline-button compact-button">Record move-out</button></form><?php endif; ?></td></tr><?php endforeach; if(!$allocations): ?><tr><td colspan="6" class="empty-cell">No learner boarding allocations yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?><section class="panel info-panel"><h2>Boarding information</h2><p>This view only shows accommodation linked to learner contacts for which you have granted portal consent.</p><?php if(!$guardianChildren): ?><p>No consented learner links are available on this account.</p><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Learner</th><th>Room</th><th>House</th><th>House parent</th><th>Dates</th><th>Status</th></tr></thead><tbody><?php foreach($guardianChildren as $child): $childRows=array_values(array_filter($allocations,static fn($a)=>(int)$a['student_id']===(int)$child['id'])); if(!$childRows): ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td colspan="5">No boarding assignment recorded.</td></tr><?php else: foreach($childRows as $allocation): $current=$allocation['status']==='Active'&&$allocation['start_on']<=date('Y-m-d')&&(!$allocation['end_on']||$allocation['end_on']>=date('Y-m-d')); ?><tr><td><?= h($child['first_name'].' '.$child['last_name']) ?> · Form <?= (int)$child['form_level'] ?></td><td><?= h($allocation['room_name']) ?></td><td><?= h($allocation['boarding_house']?:'—') ?></td><td><?= h($allocation['house_parent']?:'Unassigned') ?></td><td><?= h(date('d M Y',strtotime($allocation['start_on']))) ?> – <?= $allocation['end_on']?h(date('d M Y',strtotime($allocation['end_on']))):'Current' ?></td><td><?= $current?'Current':($allocation['status']==='Active'?'Scheduled':h($allocation['status'])) ?></td></tr><?php endforeach; endif; endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
